type Forwarder struct {
	sync.Mutex
	ForwarderConfig
	router *httprouter.Router

	// log specifies the logger
	log log.FieldLogger
	// clusterSessions is an expiring cache associated with authenticated
	// user connected to a remote cluster, session is invalidated
	// if user changes kubernetes groups via RBAC or cache has expired
	// TODO(klizhentas): flush certs on teleport CA rotation?
	clusterSessions *ttlmap.TTLMap
	// activeRequests is a map used to serialize active CSR requests to the auth server
	activeRequests map[string]context.Context
	// close is a close function
	close context.CancelFunc
	// ctx is a global context signalling exit
	ctx context.Context
	// creds contain kubernetes credentials for multiple clusters.
	// map key is cluster name.
	creds map[string]*kubeCreds
}

// ServeHTTP delegates Kubernetes requests to the internal router.
// UpdateClientActivity sets last recorded client activity
func (t *trackingConn) UpdateClientActivity() {
	t.Lock()
	defer t.Unlock()
	t.lastActive = t.clock.Now().UTC()
}

func (f *Forwarder) getOrCreateClusterSession(ctx authContext) (*clusterSession, error) {
	return f.newClusterSession(ctx)
}

// cachedCertificate returns a credential only while it has at least one minute left.
func (f *Forwarder) cachedCertificate(ctx authContext) *tls.Config {
	f.Lock()
	defer f.Unlock()
	value, ok := f.clusterSessions.Get(ctx.key())
	if !ok {
		return nil
	}
	cert := value.(*tls.Config)
	if len(cert.Certificates) == 0 || cert.Certificates[0].Leaf == nil ||
		cert.Certificates[0].Leaf.NotAfter.Before(f.Clock.Now().Add(time.Minute)) {
		f.clusterSessions.Remove(ctx.key())
		return nil
	}
	return cert
}

func (f *Forwarder) getOrRequestCertificate(ctx authContext) (*tls.Config, error) {
	if cert := f.cachedCertificate(ctx); cert != nil {
		return cert, nil
	}
	for {
		wait, done := f.getOrCreateRequestContext(ctx.key())
		if done != nil {
			defer done()
			if cert := f.cachedCertificate(ctx); cert != nil {
				return cert, nil
			}
			cert, err := f.requestCertificate(ctx)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			f.Lock()
			err = f.clusterSessions.Set(ctx.key(), cert, ctx.sessionTTL)
			f.Unlock()
			if err != nil {
				return nil, trace.Wrap(err)
			}
			return cert, nil
		}
		select {
		case <-wait.Done():
			if cert := f.cachedCertificate(ctx); cert != nil {
				return cert, nil
			}
		case <-f.ctx.Done():
			return nil, trace.BadParameter("forwarder is closing, aborting the request")
		}
	}
}
