	if f.CachingAuthClient == nil {
		return trace.BadParameter("missing parameter CachingAuthClient")
	}
	if f.Authz == nil {
		return trace.BadParameter("missing parameter Authz")
	}
	if f.StreamEmitter == nil {
		return trace.BadParameter("missing parameter StreamEmitter")
	}
	if f.ClusterName == "" {
		return trace.BadParameter("missing parameter LocalCluster")
	}
	if f.Keygen == nil {
		return trace.BadParameter("missing parameter Keygen")
	}
	if f.DataDir == "" {
		return trace.BadParameter("missing parameter DataDir")
	}
	if f.ServerID == "" {
		return trace.BadParameter("missing parameter ServerID")
	}
	if f.Namespace == "" {
		f.Namespace = defaults.Namespace
	}
	if f.Context == nil {
		f.Context = context.TODO()
	}
	if f.Clock == nil {
		f.Clock = clockwork.NewRealClock()
	}
	if f.ConnPingPeriod == 0 {
		f.ConnPingPeriod = defaults.HighResPollingPeriod
	}
	if f.Component == "" {
		f.Component = "kube_forwarder"
	}
	if f.KubeClusterName == "" && f.KubeconfigPath == "" {
		// Running without a kubeconfig and explicit k8s cluster name. Use
		// teleport cluster name instead, to ask kubeutils.GetKubeConfig to
		// attempt loading the in-cluster credentials.
		f.KubeClusterName = f.ClusterName
	}
	return nil
}

	defer t.Unlock()
	t.lastActive = t.clock.Now().UTC()
}

func (f *Forwarder) getOrCreateClusterSession(ctx authContext) (*clusterSession, error) {
	return f.newClusterSession(ctx)
}

// cachedCertificate returns a credential only while it has at least one minute left.
func (f *Forwarder) cachedCertificate(ctx authContext) *tls.Config {
	f.Lock()
	defer f.Unlock()
	value, ok := f.credentialCache.Get(ctx.key())
	if !ok {
		return nil
	}
	cert := value.(*tls.Config)
	if len(cert.Certificates) == 0 || cert.Certificates[0].Leaf == nil ||
		cert.Certificates[0].Leaf.NotAfter.Before(f.Clock.Now().Add(time.Minute)) {
		f.credentialCache.Remove(ctx.key())
		return nil
	}
	return cert
}

func (f *Forwarder) getOrRequestCertificate(ctx authContext) (*tls.Config, error) {
	if cert := f.cachedCertificate(ctx); cert != nil {
		return cert, nil
	}
	for {
		wait, done := f.getOrCreateRequestContext(ctx.key())
		if done != nil {
			defer done()
			if cert := f.cachedCertificate(ctx); cert != nil {
				return cert, nil
			}
			cert, err := f.requestCertificate(ctx)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			f.Lock()
			err = f.credentialCache.Set(ctx.key(), cert, ctx.sessionTTL)
			f.Unlock()
			if err != nil {
				return nil, trace.Wrap(err)
			}
			return cert, nil
		}
		select {
		case <-wait.Done():
			if cert := f.cachedCertificate(ctx); cert != nil {
				return cert, nil
			}
		case <-f.ctx.Done():
			return nil, trace.BadParameter("forwarder is closing, aborting the request")
		}
	}
}

